set-status.code:
@{
                var requestedModel = context.Request.MatchedParameters.GetValueOrDefault("model", "");
                if (string.IsNullOrEmpty(requestedModel))
                {
                    return 200;
                }

                var configuredModels = JArray.Parse(Encoding.UTF8.GetString(Convert.FromBase64String("__MODEL_NAMES_BASE64__")));
                var roles = ((Jwt)context.Variables["jwt"]).Claims
                    .GetValueOrDefault("roles", "")
                    .Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries);
                return configuredModels.Values<string>().Any(model =>
                    model.Equals(requestedModel, StringComparison.OrdinalIgnoreCase)
                    && roles.Any(role => role.Trim().Equals(model, StringComparison.OrdinalIgnoreCase)))
                    ? 200
                    : 404;
            }

set-status.reason:
@{
                var requestedModel = context.Request.MatchedParameters.GetValueOrDefault("model", "");
                if (string.IsNullOrEmpty(requestedModel))
                {
                    return "OK";
                }

                var configuredModels = JArray.Parse(Encoding.UTF8.GetString(Convert.FromBase64String("__MODEL_NAMES_BASE64__")));
                var roles = ((Jwt)context.Variables["jwt"]).Claims
                    .GetValueOrDefault("roles", "")
                    .Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries);
                return configuredModels.Values<string>().Any(model =>
                    model.Equals(requestedModel, StringComparison.OrdinalIgnoreCase)
                    && roles.Any(role => role.Trim().Equals(model, StringComparison.OrdinalIgnoreCase)))
                    ? "OK"
                    : "Not Found";
            }

return-response.set-body:
@{
                var configuredModels = JArray.Parse(Encoding.UTF8.GetString(Convert.FromBase64String("__MODEL_NAMES_BASE64__")));
                var roles = ((Jwt)context.Variables["jwt"]).Claims
                    .GetValueOrDefault("roles", "")
                    .Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries);
                var authorizedModels = configuredModels.Values<string>()
                    .Where(model => roles.Any(role => role.Trim().Equals(model, StringComparison.OrdinalIgnoreCase)))
                    .ToArray();
                var requestedModel = context.Request.MatchedParameters.GetValueOrDefault("model", "");

                if (!string.IsNullOrEmpty(requestedModel))
                {
                    var model = authorizedModels.FirstOrDefault(name =>
                        name.Equals(requestedModel, StringComparison.OrdinalIgnoreCase));
                    if (model == null)
                    {
                        return new JObject(
                            new JProperty("error", new JObject(
                                new JProperty("message", string.Format("The model '{0}' does not exist or you do not have access to it.", requestedModel)),
                                new JProperty("type", "invalid_request_error"),
                                new JProperty("param", "model"),
                                new JProperty("code", "model_not_found")
                            ))
                        ).ToString();
                    }

                    return new JObject(
                        new JProperty("id", model),
                        new JProperty("object", "model"),
                        new JProperty("created", 0),
                        new JProperty("owned_by", "azure")
                    ).ToString();
                }

                var data = new JArray();
                foreach (var model in authorizedModels)
                {
                    data.Add(new JObject(
                        new JProperty("id", model),
                        new JProperty("object", "model"),
                        new JProperty("created", 0),
                        new JProperty("owned_by", "azure")
                    ));
                }

                return new JObject(
                    new JProperty("object", "list"),
                    new JProperty("data", data)
                ).ToString();
            }
